        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }
        if (!postcode.matches("\\d{4}")) {
            errors.add("postcode");
            return;
        }
        String city = request.getCity();
        String region = city == null ? null : CITY_REGIONS.get(city);
        if (region == null) {
